import pathlib, itertools, os
root=pathlib.Path('/workspace/repo-vul/src-vul')
for p in itertools.chain((root/'Packet++').rglob('*'), (root/'Common++').rglob('*'), (root/'Tests/Fuzzers').rglob('*')):
    if p.is_file() and p.suffix in ['.cpp','.h','.hpp','.c']:
        try:
            txt=p.read_text(errors='ignore')
        except Exception: continue
        if 'SomeIpSdIPv6Option' in txt or 'IPv6Address::IPv6Address' in txt:
            print(p)
            for i,l in enumerate(txt.splitlines(),1):
                if 'SomeIpSdIPv6Option' in l or 'IPv6Address::IPv6Address' in l:
                    print(i, l[:200])
            print('---')
